9: // Generate an internal UID to make the regexp pattern harder to guess.
10: var UID                 = Math.floor(Math.random() * 0x10000000000).toString(16);
11: var PLACE_HOLDER_REGEXP = new RegExp('"@__(F|R|D|M|S|U|I)-' + UID + '-(\\d+)__@"', 'g');
12: 
13: var IS_NATIVE_CODE_REGEXP = /\{\s*\[native code\]\s*\}/g;
14: var IS_PURE_FUNCTION = /function.*?\(/;
15: var IS_ARROW_FUNCTION = /.*?=>.*?/;
16: var UNSAFE_CHARS_REGEXP   = /[<>\/\u2028\u2029]/g;
17: 
18: var RESERVED_SYMBOLS = ['*', 'async'];
19: 
20: // Mapping of unsafe HTML and invalid JavaScript line terminator chars to their
21: // Unicode char counterparts which are safe to use in JavaScript strings.
22: var ESCAPED_CHARS = {
23:     '<'     : '\\u003C',
24:     '>'     : '\\u003E',
25:     '/'     : '\\u002F',
26:     '\u2028': '\\u2028',
27:     '\u2029': '\\u2029'
28: };
