34: function deleteFunctions(obj){
35:     var functionKeys = [];
36:     for (var key in obj) {
37:         if (typeof obj[key] === "function") {
38:             functionKeys.push(key);
39:         }
40:     }
41:     for (var i = 0; i < functionKeys.length; i++) {
42:         delete obj[functionKeys[i]];
43:     }
44: }
