46: module.exports = function serialize(obj, options) {
47:     options || (options = {});
48: 
49:     // Backwards-compatibility for `space` as the second argument.
50:     if (typeof options === 'number' || typeof options === 'string') {
51:         options = {space: options};
52:     }
53: 
54:     var functions = [];
55:     var regexps   = [];
56:     var dates     = [];
57:     var maps      = [];
58:     var sets      = [];
59:     var undefs    = [];
60:     var infinities= [];
61: 
62:     // Returns placeholders for functions and regexps (identified by index)
63:     // which are later replaced by their string representation.
64:     function replacer(key, value) {
65: 
66:         // For nested function
67:         if(options.ignoreFunction){
68:             deleteFunctions(value);
69:         }
70: 
71:         if (!value && value !== undefined) {
72:             return value;
73:         }
74: 
75:         // If the value is an object w/ a toJSON method, toJSON is called before
76:         // the replacer runs, so we use this[key] to get the non-toJSONed value.
77:         var origValue = this[key];
78:         var type = typeof origValue;
79: 
80:         if (type === 'object') {
81:             if(origValue instanceof RegExp) {
82:                 return '@__R-' + UID + '-' + (regexps.push(origValue) - 1) + '__@';
83:             }
84: 
85:             if(origValue instanceof Date) {
86:                 return '@__D-' + UID + '-' + (dates.push(origValue) - 1) + '__@';
87:             }
88: 
89:             if(origValue instanceof Map) {
90:                 return '@__M-' + UID + '-' + (maps.push(origValue) - 1) + '__@';
91:             }
92: 
93:             if(origValue instanceof Set) {
94:                 return '@__S-' + UID + '-' + (sets.push(origValue) - 1) + '__@';
95:             }
96:         }
97: 
98:         if (type === 'function') {
99:             return '@__F-' + UID + '-' + (functions.push(origValue) - 1) + '__@';
100:         }
101: 
102:         if (type === 'undefined') {
103:             return '@__U-' + UID + '-' + (undefs.push(origValue) - 1) + '__@';
104:         }
105: 
106:         if (type === 'number' && !isNaN(origValue) && !isFinite(origValue)) {
107:             return '@__I-' + UID + '-' + (infinities.push(origValue) - 1) + '__@';
108:         }
109: 
110:         return value;
111:     }
112: 
113:     function serializeFunc(fn) {
114:       var serializedFn = fn.toString();
115:       if (IS_NATIVE_CODE_REGEXP.test(serializedFn)) {
116:           throw new TypeError('Serializing native function: ' + fn.name);
117:       }
118: 
119:       // pure functions, example: {key: function() {}}
120:       if(IS_PURE_FUNCTION.test(serializedFn)) {
121:           return serializedFn;
122:       }
123: 
124:       // arrow functions, example: arg1 => arg1+5
125:       if(IS_ARROW_FUNCTION.test(serializedFn)) {
126:           return serializedFn;
127:       }
128: 
129:       var argsStartsAt = serializedFn.indexOf('(');
130:       var def = serializedFn.substr(0, argsStartsAt)
131:         .trim()
132:         .split(' ')
133:         .filter(function(val) { return val.length > 0 });
134: 
135:       var nonReservedSymbols = def.filter(function(val) {
136:         return RESERVED_SYMBOLS.indexOf(val) === -1
137:       });
138: 
139:       // enhanced literal objects, example: {key() {}}
140:       if(nonReservedSymbols.length > 0) {
141:           return (def.indexOf('async') > -1 ? 'async ' : '') + 'function'
142:             + (def.join('').indexOf('*') > -1 ? '*' : '')
143:             + serializedFn.substr(argsStartsAt);
144:       }
145: 
146:       // arrow functions
147:       return serializedFn;
148:     }
149: 
150:     // Check if the parameter is function
151:     if (options.ignoreFunction && typeof obj === "function") {
152:         obj = undefined;
153:     }
154:     // Protects against `JSON.stringify()` returning `undefined`, by serializing
155:     // to the literal string: "undefined".
156:     if (obj === undefined) {
157:         return String(obj);
158:     }
159: 
160:     var str;
161: 
162:     // Creates a JSON string representation of the value.
163:     // NOTE: Node 0.12 goes into slow mode with extra JSON.stringify() args.
164:     if (options.isJSON && !options.space) {
165:         str = JSON.stringify(obj);
166:     } else {
167:         str = JSON.stringify(obj, options.isJSON ? null : replacer, options.space);
168:     }
169: 
170:     // Protects against `JSON.stringify()` returning `undefined`, by serializing
171:     // to the literal string: "undefined".
172:     if (typeof str !== 'string') {
173:         return String(str);
174:     }
175: 
176:     // Replace unsafe HTML and invalid JavaScript line terminator chars with
177:     // their safe Unicode char counterpart. This _must_ happen before the
178:     // regexps and functions are serialized and added back to the string.
179:     if (options.unsafe !== true) {
180:         str = str.replace(UNSAFE_CHARS_REGEXP, escapeUnsafeChars);
181:     }
182: 
183:     if (functions.length === 0 && regexps.length === 0 && dates.length === 0 && maps.length === 0 && sets.length === 0 && undefs.length === 0 && infinities.length === 0) {
184:         return str;
185:     }
186: 
187:     // Replaces all occurrences of function, regexp, date, map and set placeholders in the
188:     // JSON string with their string representations. If the original value can
189:     // not be found, then `undefined` is used.
190:     return str.replace(PLACE_HOLDER_REGEXP, function (match, type, valueIndex) {
191:         if (type === 'D') {
192:             return "new Date(\"" + dates[valueIndex].toISOString() + "\")";
193:         }
194: 
195:         if (type === 'R') {
196:             return "new RegExp(" + serialize(regexps[valueIndex].source) + ", \"" + regexps[valueIndex].flags + "\")";
197:         }
198: 
199:         if (type === 'M') {
200:             return "new Map(" + serialize(Array.from(maps[valueIndex].entries()), options) + ")";
201:         }
202: 
203:         if (type === 'S') {
204:             return "new Set(" + serialize(Array.from(sets[valueIndex].values()), options) + ")";
205:         }
206: 
207:         if (type === 'U') {
208:             return 'undefined'
209:         }
210: 
211:         if (type === 'I') {
212:             return infinities[valueIndex];
213:         }
214: 
215:         var fn = functions[valueIndex];
216: 
217:         return serializeFunc(fn);
218:     });
219: }",
